func TestFilter(t *testing.T) {
	scores := map[string]int{"a": 1, "b": 2, "c": 3}
	t.Run("predicate on value", func(t *testing.T) {
		even := maps.Filter(scores, func(k string, v int) bool { return v%2 == 0 })
		test.AssertEqual(t, len(even), 1)
		test.AssertEqual(t, even["b"], 2)
	})
	t.Run("predicate on key", func(t *testing.T) {
		aOnly := maps.Filter(scores, func(k string, v int) bool { return k == "a" })
		test.AssertEqual(t, len(aOnly), 1)
		_, hasC := aOnly["c"]
		test.AssertEqual(t, hasC, false)
	})
	t.Run("keep none yields empty", func(t *testing.T) {
		none := maps.Filter(scores, func(k string, v int) bool { return false })
		test.AssertEqual(t, len(none), 0)
	})
	t.Run("input untouched", func(t *testing.T) {
		maps.Filter(scores, func(k string, v int) bool { return v > 1 })
		test.AssertEqual(t, len(scores), 3)
	})
}

