func TestCloneIsolatesMutation(t *testing.T) {
	original := map[string]int{"a": 1, "b": 2}
	copy := maps.Clone(original)
	test.AssertEqual(t, len(copy), 2)
	copy["c"] = 3
	test.AssertEqual(t, len(original), 2)
	_, cInOriginal := original["c"]
	test.AssertEqual(t, cInOriginal, false)
	original["d"] = 4
	_, dInCopy := copy["d"]
	test.AssertEqual(t, dInCopy, false)
	clonedEmpty := maps.Clone(map[string]int{})
	test.AssertEqual(t, len(clonedEmpty), 0)
	clonedEmpty["x"] = 1
	test.AssertEqual(t, len(clonedEmpty), 1)
}

func TestSetOperationsDoNotMutateInputs(t *testing.T) {
	base := map[string]int{"a": 1, "b": 2}
	overlay := map[string]int{"b": 20, "c": 3}
	merged := maps.Merge(base, overlay)
	test.AssertEqual(t, merged["b"], 20)
	test.AssertEqual(t, base["b"], 2)
	test.AssertEqual(t, len(base), 2)
	test.AssertEqual(t, len(overlay), 2)
	config := map[string]int{"host": 1, "port": 2, "debug": 3}
	picked := maps.Pick(config, []string{"host", "port", "absent"})
	test.AssertEqual(t, len(picked), 2)
	test.AssertEqual(t, len(config), 3)
	omitted := maps.Omit(config, []string{"debug", "absent"})
	test.AssertEqual(t, len(omitted), 2)
	test.AssertEqual(t, len(config), 3)
	_, debugStillThere := config["debug"]
	test.AssertEqual(t, debugStillThere, true)
}

